#!/usr/bin/python3
"""Merge transaction CSV exports safely and in numeric transaction-id order."""

import csv
import os
import re
import sys
import tempfile
from pathlib import Path


BASE = Path(__file__).resolve().parent.parent
OUTPUT = BASE / "merged.csv"
INTEGER_ID = re.compile(r"[+-]?[0-9]+")


class MergeError(Exception):
    pass


def row_text(row):
    return repr(row)


def merge(paths):
    header = None
    id_column = None
    records = {}
    origins = {}

    if not paths:
        raise MergeError("no input CSV files were supplied and exports/ is empty")

    for path in paths:
        try:
            stream = path.open("r", encoding="utf-8-sig", newline="")
        except OSError as exc:
            raise MergeError(f"cannot open {path}: {exc.strerror}") from exc

        with stream:
            reader = csv.reader(stream, strict=True)
            try:
                candidate_header = next(reader)
            except StopIteration:
                raise MergeError(f"{path}: empty CSV file")
            except csv.Error as exc:
                raise MergeError(f"{path}: invalid CSV header: {exc}") from exc

            if header is None:
                header = candidate_header
                if header.count("transaction_id") != 1:
                    raise MergeError(
                        f"{path}: header must contain transaction_id exactly once"
                    )
                id_column = header.index("transaction_id")
            elif candidate_header != header:
                raise MergeError(
                    f"{path}: header {candidate_header!r} does not match "
                    f"the first input header {header!r}"
                )

            try:
                for line_number, row in enumerate(reader, start=2):
                    if len(row) != len(header):
                        raise MergeError(
                            f"{path}:{line_number}: expected {len(header)} fields, "
                            f"found {len(row)}"
                        )

                    raw_id = row[id_column]
                    if INTEGER_ID.fullmatch(raw_id) is None:
                        raise MergeError(
                            f"{path}:{line_number}: transaction_id {raw_id!r} "
                            "is not an integer"
                        )
                    numeric_id = int(raw_id, 10)

                    if numeric_id in records:
                        if row != records[numeric_id]:
                            previous_path, previous_line = origins[numeric_id]
                            raise MergeError(
                                f"conflicting duplicate transaction_id {raw_id!r}: "
                                f"{previous_path}:{previous_line} has "
                                f"{row_text(records[numeric_id])}; "
                                f"{path}:{line_number} has {row_text(row)}"
                            )
                        continue

                    records[numeric_id] = row
                    origins[numeric_id] = (path, line_number)
            except csv.Error as exc:
                raise MergeError(f"{path}: invalid CSV data: {exc}") from exc

    existing_mode = 0o644
    try:
        existing_mode = OUTPUT.stat().st_mode & 0o777
    except FileNotFoundError:
        pass

    temporary_name = None
    try:
        with tempfile.NamedTemporaryFile(
            mode="w",
            encoding="utf-8",
            newline="",
            prefix=".merged.csv.",
            dir=BASE,
            delete=False,
        ) as temporary:
            temporary_name = temporary.name
            writer = csv.writer(temporary, lineterminator="\n")
            writer.writerow(header)
            for numeric_id in sorted(records):
                writer.writerow(records[numeric_id])
            temporary.flush()
            os.fsync(temporary.fileno())

        os.chmod(temporary_name, existing_mode)
        os.replace(temporary_name, OUTPUT)
        temporary_name = None
    finally:
        if temporary_name is not None:
            try:
                os.unlink(temporary_name)
            except FileNotFoundError:
                pass


def main():
    if len(sys.argv) > 1:
        paths = [Path(argument) for argument in sys.argv[1:]]
    else:
        paths = sorted((BASE / "exports").glob("*.csv"))

    try:
        merge(paths)
    except (MergeError, OSError) as exc:
        print(f"merge: {exc}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
